// Internet Speed Monitor — Cinnamon applet
// Shows the real download/upload speed of the interfaces carrying traffic
// to the Internet (Wi-Fi, USB tethering, Ethernet, modem), with mini graphs.
//
// This applet was written with the help of AI: the code, translations and
// documentation were generated by Claude Opus 5.5 (Anthropic, model id
// claude-opus-5-5) through Claude Code, then tested and published by vitino70.

const Applet = imports.ui.applet;
const PopupMenu = imports.ui.popupMenu;
const Settings = imports.ui.settings;
const Util = imports.misc.util;
const St = imports.gi.St;
const GLib = imports.gi.GLib;
const Clutter = imports.gi.Clutter;
const Gettext = imports.gettext;

const UUID = 'internet-speed-monitor@vitino70';
Gettext.bindtextdomain(UUID, GLib.get_home_dir() + '/.local/share/locale');

function _(str) {
    let t = Gettext.dgettext(UUID, str);
    return t !== str ? t : Gettext.gettext(str);
}

const HISTORY = 160;          // samples kept
const PANEL_STEP = 2;         // pixels per sample in the panel graphs
const SYS = '/sys/class/net/';

const decoder = new TextDecoder();

function readFile(path) {
    try {
        let [ok, data] = GLib.file_get_contents(path);
        return ok ? decoder.decode(data) : null;
    } catch (e) {
        return null;
    }
}

function exists(path) {
    return GLib.file_test(path, GLib.FileTest.EXISTS);
}

// --- Kernel data -----------------------------------------------------------

function readNetDev() {
    let out = {};
    let txt = readFile('/proc/net/dev');
    if (!txt) return out;
    for (let line of txt.split('\n').slice(2)) {
        let i = line.indexOf(':');
        if (i < 0) continue;
        let name = line.slice(0, i).trim();
        let f = line.slice(i + 1).trim().split(/\s+/);
        out[name] = { rx: Number(f[0]), tx: Number(f[8]) };
    }
    return out;
}

// Interfaces holding a default route (IPv4 or IPv6), i.e. going to the Internet
function defaultRouteIfaces() {
    let set = new Set();
    let v4 = readFile('/proc/net/route');
    if (v4) {
        for (let line of v4.split('\n').slice(1)) {
            let f = line.trim().split(/\s+/);
            if (f.length < 8) continue;
            let flags = parseInt(f[3], 16);
            if (f[1] === '00000000' && f[7] === '00000000' && (flags & 1))
                set.add(f[0]);
        }
    }
    let v6 = readFile('/proc/net/ipv6_route');
    if (v6) {
        for (let line of v6.split('\n')) {
            let f = line.trim().split(/\s+/);
            if (f.length < 10) continue;
            let flags = parseInt(f[8], 16);
            if (/^0+$/.test(f[0]) && f[1] === '00' && f[9] !== 'lo' &&
                (flags & 0x1) && !(flags & 0x200))
                set.add(f[9]);
        }
    }
    return set;
}

function isPhysical(name) {
    return exists(SYS + name + '/device');
}

function isUp(name) {
    let s = readFile(SYS + name + '/operstate');
    s = s ? s.trim() : '';
    return s === 'up' || s === 'unknown';
}

function ifaceKind(name) {
    if (exists(SYS + name + '/wireless') || exists(SYS + name + '/phy80211'))
        return 'wifi';
    if (/^(ppp|wwan|wwp)/.test(name))
        return 'mobile';
    if (/^(tun|tap|wg|vpn|tailscale|zt)/.test(name))
        return 'vpn';
    if (isPhysical(name)) {
        let driver = '';
        try {
            driver = GLib.path_get_basename(GLib.file_read_link(SYS + name + '/device/driver'));
        } catch (e) { }
        if (/^(qmi_wwan|cdc_mbim)$/.test(driver)) return 'mobile';
        if (/^(rndis_host|cdc_ether|cdc_ncm|ipheth|r8152_usb_tether)$/.test(driver)) return 'usb';
        try {
            let real = GLib.file_read_link(SYS + name);
            if (real.indexOf('/usb') >= 0 && /^(usb|enx)/.test(name)) return 'usb';
        } catch (e) { }
        return 'ethernet';
    }
    return 'other';
}

const KIND_INFO = {
    wifi:     { label: _("Wi-Fi"),          icon: 'network-wireless-symbolic' },
    usb:      { label: _("USB tethering"),  icon: 'phone-symbolic' },
    mobile:   { label: _("Mobile network"), icon: 'network-cellular-symbolic' },
    ethernet: { label: _("Ethernet"),       icon: 'network-wired-symbolic' },
    vpn:      { label: _("VPN"),            icon: 'network-vpn-symbolic' },
    other:    { label: _("Network"),        icon: 'network-transmit-receive-symbolic' }
};

// --- Formatting ----------------------------------------------------------

function parseColor(s) {
    let m = /rgba?\(([^)]+)\)/.exec(s || '');
    if (m) {
        let p = m[1].split(',').map(x => parseFloat(x));
        return [p[0] / 255, p[1] / 255, p[2] / 255, p.length > 3 ? p[3] : 1];
    }
    m = /^#([0-9a-f]{6})/i.exec(s || '');
    if (m) {
        let n = parseInt(m[1], 16);
        return [(n >> 16 & 255) / 255, (n >> 8 & 255) / 255, (n & 255) / 255, 1];
    }
    return [0.5, 0.5, 0.5, 1];
}

// Returns [number (4 chars), unit] for a speed in bytes/s
function splitSpeed(bytesPerSec, bits) {
    let v = bits ? bytesPerSec * 8 : bytesPerSec;
    let units = bits ? ['b/s', 'kb/s', 'Mb/s', 'Gb/s'] : ['B/s', 'kB/s', 'MB/s', 'GB/s'];
    let u = 0;
    while (v >= 999.5 && u < units.length - 1) { v /= 1000; u++; }
    let s;
    if (u === 0) s = Math.round(v).toString();
    else if (v < 9.995) s = v.toFixed(2);
    else if (v < 99.95) s = v.toFixed(1);
    else s = Math.round(v).toString();
    return [s, units[u]];
}

function formatSpeed(bytesPerSec, bits, pad) {
    let [n, u] = splitSpeed(bytesPerSec, bits);
    return pad ? n.padStart(4) + ' ' + u.padEnd(4) : n + ' ' + u;
}

function formatShort(bytesPerSec, bits) {
    let [n, u] = splitSpeed(bytesPerSec, bits);
    let v = parseFloat(n);
    let suffix = { k: 'K', M: 'M', G: 'G' }[u[0]] || '';
    return (v >= 10 ? Math.round(v).toString() : v.toFixed(1)) + suffix;
}

function formatBytes(b) {
    let units = ['B', 'kB', 'MB', 'GB', 'TB'];
    let u = 0;
    while (b >= 1000 && u < units.length - 1) { b /= 1000; u++; }
    return (u === 0 ? b.toString() : b.toFixed(b < 10 ? 2 : 1)) + ' ' + units[u];
}

// --- Applet ---------------------------------------------------------------

class InternetSpeedMonitor extends Applet.Applet {
    constructor(metadata, orientation, panelHeight, instanceId) {
        super(orientation, panelHeight, instanceId);
        this.setAllowedLayout(Applet.AllowedLayout.BOTH);

        this._orientation = orientation;
        this._timerId = 0;
        this._prev = {};          // previous counters per interface
        this._lastTime = 0;
        this._ifaces = [];        // [{name, kind, rx, tx, down, up}]
        this._ifaceKey = null;
        this._histDown = new Array(HISTORY).fill(0);
        this._histUp = new Array(HISTORY).fill(0);
        this._down = 0;
        this._up = 0;
        this._peakDown = 0;
        this._peakUp = 0;
        this._ips = {};

        this.settings = new Settings.AppletSettings(this, metadata.uuid, instanceId);
        let rebuild = () => this._buildPanel();
        this.settings.bind('update-interval', 'updateInterval', () => this._startTimer());
        this.settings.bind('unit', 'unit', () => this._refreshText());
        this.settings.bind('iface-mode', 'ifaceMode', () => this._tick());
        this.settings.bind('manual-ifaces', 'manualIfaces', () => this._tick());
        this.settings.bind('show-graphs', 'showGraphs', rebuild);
        this.settings.bind('graph-mode', 'graphMode', rebuild);
        this.settings.bind('graph-width', 'graphWidth', rebuild);
        this.settings.bind('graph-scale', 'graphScale', () => this._repaintAll());
        this.settings.bind('show-text', 'showText', rebuild);
        this.settings.bind('text-layout', 'textLayout', rebuild);
        this.settings.bind('color-down', 'colorDown', rebuild);
        this.settings.bind('color-up', 'colorUp', rebuild);
        this.settings.bind('color-text', 'colorText', rebuild);

        this.menuManager = new PopupMenu.PopupMenuManager(this);
        this.menu = new Applet.AppletPopupMenu(this, orientation);
        this.menuManager.addMenu(this.menu);
        this._buildMenu();
        this.menu.connect('open-state-changed', (m, open) => {
            if (open) { this._fetchIps(); this._updateMenu(); }
        });

        this._buildPanel();
        this._startTimer();
    }

    get _bits() { return this.unit === 'bits'; }
    get _vertical() {
        return this._orientation === St.Side.LEFT || this._orientation === St.Side.RIGHT;
    }

    // --- Panel -----------------------------------------------------------

    _buildPanel() {
        this.actor.destroy_all_children();
        this._graphs = [];
        this._lblDown = this._lblUp = null;

        let scale = St.ThemeContext.get_for_stage(global.stage).scale_factor || 1;
        let ph = this._panelHeight / scale;
        let vertical = this._vertical;

        this._nsmBox = new St.BoxLayout({ style_class: 'nsm-box', vertical: vertical,
                                       y_align: Clutter.ActorAlign.CENTER });
        this.actor.add_child(this._nsmBox);

        let cDown = parseColor(this.colorDown), cUp = parseColor(this.colorUp);

        if (this.showGraphs) {
            let gw = vertical ? Math.max(16, Math.round(ph) - 8) : this.graphWidth;
            let gh = vertical ? 18 : Math.max(12, Math.round(ph) - 10);
            let defs = this.graphMode === 'combined'
                ? [[{ hist: this._histDown, color: cDown }, { hist: this._histUp, color: cUp }]]
                : [[{ hist: this._histDown, color: cDown }], [{ hist: this._histUp, color: cUp }]];
            for (let series of defs) {
                let area = new St.DrawingArea({ style: `width: ${gw}px; height: ${gh}px;`,
                                                y_align: Clutter.ActorAlign.CENTER });
                area.connect('repaint', (a) => this._paintArea(a, series, PANEL_STEP));
                this._nsmBox.add_child(area);
                this._graphs.push(area);
            }
        }

        if (this.showText) {
            let stacked = vertical || this.textLayout === 'stacked';
            let textBox = new St.BoxLayout({ style_class: 'nsm-text-box', vertical: stacked,
                                             y_align: Clutter.ActorAlign.CENTER });
            let cls = stacked ? 'nsm-label' : 'nsm-label-inline';
            let css = c => this.colorText
                ? `color: rgb(${Math.round(c[0] * 255)},${Math.round(c[1] * 255)},${Math.round(c[2] * 255)});` : '';
            this._lblDown = new St.Label({ style_class: cls, style: css(cDown), y_align: Clutter.ActorAlign.CENTER });
            this._lblUp = new St.Label({ style_class: cls, style: css(cUp), y_align: Clutter.ActorAlign.CENTER });
            textBox.add_child(this._lblDown);
            textBox.add_child(this._lblUp);
            this._nsmBox.add_child(textBox);
        }

        if (!this.showGraphs && !this.showText) {
            this._nsmBox.add_child(new St.Icon({ icon_name: 'network-transmit-receive-symbolic',
                                              icon_type: St.IconType.SYMBOLIC,
                                              style_class: 'applet-icon' }));
        }

        this._refreshText();
        this._repaintAll();
    }

    _refreshText() {
        if (!this._lblDown) return;
        if (this._vertical) {
            this._lblDown.set_text('↓' + formatShort(this._down, this._bits));
            this._lblUp.set_text('↑' + formatShort(this._up, this._bits));
        } else {
            this._lblDown.set_text('↓' + formatSpeed(this._down, this._bits, true));
            this._lblUp.set_text('↑' + formatSpeed(this._up, this._bits, true));
        }
    }

    _repaintAll() {
        for (let g of this._graphs || []) g.queue_repaint();
        if (this._menuGraph && this.menu.isOpen) this._menuGraph.queue_repaint();
    }

    // Draws one or more overlapping series in a DrawingArea
    _paintArea(area, series, step) {
        let cr = area.get_context();
        let [w, h] = area.get_surface_size();
        let n = Math.min(HISTORY, Math.floor(w / step) + 1);

        let base = series.length === 1 ? series[0].color : [0.5, 0.5, 0.5, 1];
        cr.setSourceRGBA(base[0], base[1], base[2], 0.14);
        this._roundRect(cr, 0, 0, w, h, Math.min(3, h / 4));
        cr.fill();

        let max = 0;
        for (let s of series)
            for (let i = HISTORY - n; i < HISTORY; i++) max = Math.max(max, s.hist[i]);
        let log = this.graphScale === 'log';
        max = Math.max(max, log ? 100000 : 10000);   // minimum full scale: 100 kB/s log, 10 kB/s linear
        let frac = log ? (v => Math.log1p(v / 1000) / Math.log1p(max / 1000)) : (v => v / max);

        for (let s of series) {
            let c = s.color;
            cr.moveTo(w, h);
            for (let k = 0; k < n; k++) {
                let v = s.hist[HISTORY - 1 - k];
                let x = w - k * step;
                let y = h - 1 - frac(v) * (h - 2);
                cr.lineTo(Math.max(0, x), y);
            }
            cr.lineTo(Math.max(0, w - (n - 1) * step), h);
            cr.closePath();
            cr.setSourceRGBA(c[0], c[1], c[2], series.length > 1 ? 0.35 : 0.5);
            cr.fillPreserve();
            cr.newPath();

            for (let k = 0; k < n; k++) {
                let v = s.hist[HISTORY - 1 - k];
                let x = Math.max(0, w - k * step);
                let y = h - 1 - frac(v) * (h - 2);
                if (k === 0) cr.moveTo(x, y); else cr.lineTo(x, y);
            }
            cr.setSourceRGBA(c[0], c[1], c[2], 1);
            cr.setLineWidth(1.2);
            cr.stroke();
        }
        cr.$dispose();
    }

    _roundRect(cr, x, y, w, h, r) {
        cr.newSubPath();
        cr.arc(x + w - r, y + r, r, -Math.PI / 2, 0);
        cr.arc(x + w - r, y + h - r, r, 0, Math.PI / 2);
        cr.arc(x + r, y + h - r, r, Math.PI / 2, Math.PI);
        cr.arc(x + r, y + r, r, Math.PI, 3 * Math.PI / 2);
        cr.closePath();
    }

    // --- Sampling --------------------------------------------------------

    _startTimer() {
        if (this._timerId) GLib.source_remove(this._timerId);
        let ms = Math.max(250, Math.round((this.updateInterval || 1) * 1000));
        this._timerId = GLib.timeout_add(GLib.PRIORITY_DEFAULT, ms, () => {
            this._tick();
            return GLib.SOURCE_CONTINUE;
        });
        this._tick();
    }

    _selectIfaces(stats) {
        let names = Object.keys(stats).filter(n => n !== 'lo');
        if (this.ifaceMode === 'manual') {
            let wanted = (this.manualIfaces || '').split(',').map(s => s.trim()).filter(s => s);
            return wanted.filter(n => n in stats);
        }
        if (this.ifaceMode === 'physical')
            return names.filter(n => isPhysical(n) && isUp(n));

        // auto: interfaces with a default route; if some of them are physical,
        // count only those (avoids counting VPN traffic twice)
        let routes = defaultRouteIfaces();
        let def = names.filter(n => routes.has(n));
        let phys = def.filter(n => isPhysical(n));
        return phys.length ? phys : def;
    }

    _tick() {
        let now = GLib.get_monotonic_time();
        let stats = readNetDev();
        let dt = this._lastTime ? (now - this._lastTime) / 1e6 : 0;
        this._lastTime = now;

        let names = this._selectIfaces(stats);
        let down = 0, up = 0, list = [];
        for (let name of names) {
            let cur = stats[name], prev = this._prev[name];
            let d = 0, u = 0;
            if (prev && dt > 0) {
                d = Math.max(0, cur.rx - prev.rx) / dt;
                u = Math.max(0, cur.tx - prev.tx) / dt;
            }
            down += d; up += u;
            list.push({ name, rx: cur.rx, tx: cur.tx, down: d, up: u });
        }
        this._prev = stats;

        let key = names.join(',');
        if (key !== this._ifaceKey) {
            this._ifaceKey = key;
            this._kinds = {};
            for (let n of names) this._kinds[n] = ifaceKind(n);
            if (this.menu.isOpen) this._fetchIps();
            this._rebuildIfaceItems = true;
        }
        for (let it of list) it.kind = this._kinds[it.name];
        this._ifaces = list;

        this._down = down; this._up = up;
        this._peakDown = Math.max(this._peakDown, down);
        this._peakUp = Math.max(this._peakUp, up);
        this._histDown.shift(); this._histDown.push(down);
        this._histUp.shift(); this._histUp.push(up);

        this._refreshText();
        this._repaintAll();
        this._updateTooltip();
        if (this.menu.isOpen) this._updateMenu();
    }

    _updateTooltip() {
        let b = this._bits;
        let lines = [_("Internet traffic")];
        if (!this._ifaces.length) lines.push(_("No Internet connection"));
        for (let it of this._ifaces)
            lines.push(`${KIND_INFO[it.kind].label} (${it.name}):  ↓ ${formatSpeed(it.down, b)}   ↑ ${formatSpeed(it.up, b)}`);
        this.set_applet_tooltip(lines.join('\n'));
    }

    // --- Menu -------------------------------------------------------------

    _buildMenu() {
        let title = new PopupMenu.PopupMenuItem(_("Internet traffic"), { reactive: false });
        title.label.add_style_class_name('nsm-menu-title');
        this.menu.addMenuItem(title);

        let graphItem = new PopupMenu.PopupBaseMenuItem({ reactive: false });
        let gbox = new St.BoxLayout({ vertical: true, style: 'spacing: 4px;' });
        this._menuGraph = new St.DrawingArea({ style: 'width: 320px; height: 90px;' });
        this._menuGraph.connect('repaint', (a) => this._paintArea(a, [
            { hist: this._histDown, color: parseColor(this.colorDown) },
            { hist: this._histUp, color: parseColor(this.colorUp) }
        ], 320 / (HISTORY - 1)));
        this._menuSummary = new St.Label({ style_class: 'nsm-menu-mono' });
        this._menuPeak = new St.Label({ style_class: 'nsm-menu-dim' });
        gbox.add_child(this._menuGraph);
        gbox.add_child(this._menuSummary);
        gbox.add_child(this._menuPeak);
        graphItem.addActor(gbox, { span: -1, expand: true });
        this.menu.addMenuItem(graphItem);

        this.menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());
        this._ifaceSection = new PopupMenu.PopupMenuSection();
        this.menu.addMenuItem(this._ifaceSection);
        this._ifaceItems = {};

        this.menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());
        let reset = new PopupMenu.PopupIconMenuItem(_("Reset peaks"), 'edit-clear-symbolic', St.IconType.SYMBOLIC);
        reset.connect('activate', () => { this._peakDown = this._peakUp = 0; });
        this.menu.addMenuItem(reset);
        let netSettings = new PopupMenu.PopupIconMenuItem(_("Network settings"), 'preferences-system-network-symbolic', St.IconType.SYMBOLIC);
        netSettings.connect('activate', () => Util.spawnCommandLine('cinnamon-settings network'));
        this.menu.addMenuItem(netSettings);
        if (GLib.find_program_in_path('gnome-system-monitor')) {
            let sysmon = new PopupMenu.PopupIconMenuItem(_("System monitor"), 'utilities-system-monitor-symbolic', St.IconType.SYMBOLIC);
            sysmon.connect('activate', () => Util.spawnCommandLine('gnome-system-monitor -r'));
            this.menu.addMenuItem(sysmon);
        }
    }

    _updateMenu() {
        let b = this._bits;
        this._menuSummary.set_text(`↓ ${formatSpeed(this._down, b, true)}    ↑ ${formatSpeed(this._up, b, true)}`);
        this._menuPeak.set_text(_("Peak:  ↓ %s   ↑ %s").format(formatSpeed(this._peakDown, b), formatSpeed(this._peakUp, b)) +
                                '   ·   ' + _("last %d s").format(Math.round(HISTORY * (this.updateInterval || 1))));
        this._menuGraph.queue_repaint();

        if (this._rebuildIfaceItems) {
            this._rebuildIfaceItems = false;
            this._ifaceSection.removeAll();
            this._ifaceItems = {};
            if (!this._ifaces.length) {
                this._ifaceSection.addMenuItem(new PopupMenu.PopupMenuItem(_("No Internet connection"), { reactive: false }));
            }
            for (let it of this._ifaces) {
                let item = new PopupMenu.PopupBaseMenuItem({ reactive: false });
                let icon = new St.Icon({ icon_name: KIND_INFO[it.kind].icon, icon_type: St.IconType.SYMBOLIC,
                                         icon_size: 22, style: 'padding-right: 8px;' });
                let row = new St.BoxLayout();
                let col = new St.BoxLayout({ vertical: true, y_align: Clutter.ActorAlign.CENTER });
                let head = new St.Label();
                let speed = new St.Label({ style_class: 'nsm-menu-mono' });
                let total = new St.Label({ style_class: 'nsm-menu-dim' });
                col.add_child(head); col.add_child(speed); col.add_child(total);
                icon.y_align = Clutter.ActorAlign.CENTER;
                row.add_child(icon);
                row.add_child(col);
                item.addActor(row, { span: -1, expand: true });
                this._ifaceSection.addMenuItem(item);
                this._ifaceItems[it.name] = { head, speed, total };
            }
        }
        for (let it of this._ifaces) {
            let w = this._ifaceItems[it.name];
            if (!w) continue;
            let ip = this._ips[it.name] ? '   ' + this._ips[it.name] : '';
            w.head.set_text(`${KIND_INFO[it.kind].label} · ${it.name}${ip}`);
            w.speed.set_text(`↓ ${formatSpeed(it.down, b, true)}    ↑ ${formatSpeed(it.up, b, true)}`);
            w.total.set_text(_("Total since connected:  ↓ %s   ↑ %s").format(formatBytes(it.rx), formatBytes(it.tx)));
        }
    }

    _fetchIps() {
        Util.spawnCommandLineAsyncIO('ip -o -4 addr show', (stdout) => {
            let ips = {};
            for (let line of (stdout || '').split('\n')) {
                let m = /^\d+:\s+(\S+)\s+inet\s+([\d.]+)/.exec(line);
                if (m && !ips[m[1]]) ips[m[1]] = m[2];
            }
            this._ips = ips;
            if (this.menu.isOpen) this._updateMenu();
        });
    }

    // --- Applet events ----------------------------------------------------

    on_applet_clicked() {
        this.menu.toggle();
    }

    on_orientation_changed(orientation) {
        this._orientation = orientation;
        this._buildPanel();
    }

    on_panel_height_changed() {
        this._buildPanel();
    }

    on_applet_removed_from_panel() {
        if (this._timerId) GLib.source_remove(this._timerId);
        this._timerId = 0;
        this.settings.finalize();
    }
}

function main(metadata, orientation, panelHeight, instanceId) {
    return new InternetSpeedMonitor(metadata, orientation, panelHeight, instanceId);
}
